  from public.venues v
 where r.venue_id = v.id and v.slug = 'mojitos-calle-8' and r.slug = 'sala-principal'
   and coalesce(r.layout, '{}'::jsonb) = '{}'::jsonb;     -- solo si la sala aún NO tiene un mapa: nunca pisa uno ya fijado

-- Comprobación (debe devolver 1 fila con 36 mesas):
select r.slug, jsonb_array_length(r.layout -> 'tables') as mesas
  from public.venue_rooms r join public.venues v on v.id = r.venue_id
 where v.slug = 'mojitos-calle-8' and r.slug = 'sala-principal';
